var n = (flow.get('candump_restarts') || 0) + 1;
flow.set('candump_restarts', n);

var rc = (typeof msg.payload === 'object') ? JSON.stringify(msg.payload) : msg.payload;
node.warn('e-drive candump exited (rc ' + rc + ') — restart #' + n + ' in 5s');
node.status({ fill: 'red', shape: 'ring', text: 'candump exited (rc ' + rc + ') — restart #' + n });
return msg;

// candump -L lines: (ts) can0 28A#F0852742C9365842  or  (ts) can0 09F2058D#00FCFFFFFFFF00FF
let buf = context.get('buf') || '';
buf += msg.payload.toString();
const lines = buf.split('\n');
buf = lines.pop();
context.set('buf', buf);

const state = context.get('state') || { A: {}, B: {} };

for (const line of lines) {
    const m = line.match(/can0\s+([0-9A-F]{3,8})#([0-9A-F]+)/);
    if (!m) continue;
    const id = m[1], data = m[2];
    if (id.length === 8) {
        // NMEA2000 PGN 127493 transmission, matched by PGN (source address may renumber):
        // byte0 instance (00=port, 01=stbd), byte1 bits0-1 gear
        const pgn = (parseInt(id, 16) >> 8) & 0x3FFFF;
        if (pgn === 0x1F205 && data.length >= 4) {
            const inst = data.slice(0, 2);
            const motor = inst === '00' ? 'A' : (inst === '01' ? 'B' : null);
            if (motor) {
                const gear = parseInt(data.slice(2, 4), 16) & 0x03; // 0=Fwd 1=Neutral 2=Rev 3=Unknown
                if (gear !== 3) state[motor].direction = gear === 0 ? 2 : (gear === 2 ? 1 : 0); // → Venus: 0=Neutral 1=Reverse 2=Forward
            }
        }
        continue;
    }
    const motor = id.endsWith('A') ? 'A' : (id.endsWith('B') ? 'B' : null);
    if (!motor) continue;
    const s = state[motor];
    if (id[0] === '1') { s.status = parseInt(data.slice(0, 2), 16); continue; }
    if (data.length < 16) continue;
    const b = Buffer.from(data, 'hex');
    const f1 = b.readFloatLE(0), f2 = b.readFloatLE(4);
    switch (id[0]) {
        case '2': s.ctrlTemp = f1; s.motorTemp = f2; break;
        case '3': s.voltage = f1; s.phaseI = f2; break;
        case '4': s.power = f1 * 100; s.rpm = f2; break; // x100W SIGNED: + motoring, - generating (confirmed)
    }
}
context.set('state', state);

// rate-limit dbus updates to 1/s per drive
const now = Date.now();
const last = context.get('last') || { A: 0, B: 0 };
const out = [null, null];
[['A', 0], ['B', 1]].forEach(([k, i]) => {
    const s = state[k];
    if (s.rpm === undefined || now - last[k] < 1000) return;
    last[k] = now;
    const p = { 'Motor/RPM': Math.round(s.rpm) };
    if (s.voltage != null) p['Dc/0/Voltage'] = +s.voltage.toFixed(2);
    if (s.power != null) {
        p['Dc/0/Power'] = +s.power.toFixed(0);
        if (s.voltage > 1) p['Dc/0/Current'] = +(s.power / s.voltage).toFixed(1);
    }
    if (s.motorTemp != null) p['Motor/Temperature'] = +s.motorTemp.toFixed(1);
    if (s.ctrlTemp != null) p['Controller/Temperature'] = +s.ctrlTemp.toFixed(1);
    if (s.direction != null) p['Motor/Direction'] = s.direction;
    out[i] = { payload: p };
});
context.set('last', last);
return out;
